import React,{useState} from "react";
import api from "../api";

function GroceryPage(){

const [items,setItems]=useState("");

const load = async()=>{

 const res = await api.get(
  "/families/1/weekly-grocery"
 );

 setItems(res.data.items);
};

return(
<div className="page">

<h1>Weekly Grocery</h1>

<button onClick={load}>
Generate Grocery
</button>

<pre>{items}</pre>

</div>
);
}

export default GroceryPage;
